/** 播放帧间隔（ms）。9 帧 × 30ms ≈ 270ms 走完一次变形，
 *  与弹簧的"快进慢收"节奏匹配：前段帧间位移大、后段收细，读起来是有阻尼的，不是匀速。 */
export const MORPH_FRAME_MS = 30

/** 取某组帧序列；不存在时返回空数组（组件据此静默降级为静态图标） */
export const getMorphFrames = (key) => MORPH_FRAMES[key] || []
